// SATA value index — record JAH-GPC-SATASSD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"seq_read_mbs": 550, "endurance_tbw": 600};
var value = (m.seq_read_mbs/100*(m.endurance_tbw**0.5)/10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-SATASSD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-SATASSD-000001|' + value.toFixed(2) + ' value index');

